using Astrea.GameStates;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptionSourcePurgedHandler", menuName = "Data/Battle/CorruptionSourcePurgedHandler")]
public class CorruptionSourcePurgedHandler : ScriptableObject
{
	[Header("States and Events")]
	[SerializeField]
	private ChooseActionState chooseActionState;

	[SerializeField]
	private EndPlayerTurnState endPlayerTurnState;

	[SerializeField]
	private CorruptPlayerState corruptPlayerState;

	public void CorruptionSourcePurged()
	{
		corruptPlayerState.OnCorruptionSourcePurged();
		chooseActionState.OnCorruptionSourcePurged();
		endPlayerTurnState.OnCorruptionSourcePurged();
	}
}
